export { BlockEditor } from "./block-editor";
export { useBlockEditorContext } from "./context";
export { BubbleMenu } from "./bubble-menu/index";
export {
  SlashCommand,
  getSlashCommandSuggestion,
  defaultSlashCommandItems,
} from "./extensions";
export { CodeBlock } from "./extensions/code-block";
export type { SlashCommandSuggestionItem, OnCommandSelect } from "./extensions";
export type { BlockEditorProps, BlockEditorLabels } from "./types";
export { DEFAULT_BLOCK_EDITOR_LABELS } from "./labels";
export type { BlockEditorIcons } from "./icons";
export { DEFAULT_ICONS, DEFAULT_LANGUAGE_ICONS } from "./icons";

import { DragHandle } from "@tiptap/extension-drag-handle-react";
import { EditorContent } from "@tiptap/react";

import { BubbleMenu } from "./bubble-menu";
import { BlockEditorProvider, useBlockEditorContext } from "./context";
import { cn } from "./lib/utils";
import type { BlockEditorProps } from "./types";

const BlockEditorContent = () => {
  const { editor, icons } = useBlockEditorContext();

  return (
    <div className="block-editor">
      {editor && editor.isEditable && (
        <DragHandle editor={editor}>{icons.dragHandleIcon}</DragHandle>
      )}
      {editor && editor.isEditable && <BubbleMenu editor={editor} />}
      <EditorContent editor={editor} className="block-editor-content" />
    </div>
  );
};

const BlockEditorRoot = ({
  editor,
  children,
  className,
  labels,
  icons,
}: BlockEditorProps) => (
  <BlockEditorProvider editor={editor} labels={labels} icons={icons}>
    <div className={cn("block-editor", className)}>
      {children ?? <BlockEditorContent />}
    </div>
  </BlockEditorProvider>
);

export const BlockEditor = Object.assign(BlockEditorRoot, {
  BubbleMenu,
  Content: BlockEditorContent,
});

import { isTextSelection } from "@tiptap/core";
import type { Editor } from "@tiptap/react";
import { useState, useEffect, useCallback } from "react";

import { DEFAULT_ICONS } from "../icons";
import { TextAlignSelector } from "./align-selector";
import { LanguageSelector } from "./language-selector";
import { LinkSelector } from "./link-selector";
import { NodeSelector } from "./node-selector";
import { TextButtons } from "./text-buttons";
import { useEditorState } from "./utils";

export interface BubbleMenuProps {
  editor: Editor | null;
}

// Dynamic import — BubbleMenuComponent type is resolved at runtime
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let BubbleMenuComponent: any = null;

const bubbleMenuPromise = (async () => {
  try {
    // @ts-expect-error - @tiptap/react/menus only exists in v3
    const mod = await import("@tiptap/react/menus");
    BubbleMenuComponent = mod.BubbleMenu;
  } catch {
    try {
      const mod = await import("@tiptap/react");
      BubbleMenuComponent = mod.BubbleMenu;
    } catch {
      // No Tiptap BubbleMenu available
    }
  }
})();

export const BubbleMenu = ({ editor }: BubbleMenuProps) => {
  const [loaded, setLoaded] = useState(BubbleMenuComponent !== null);
  const [copied, setCopied] = useState(false);
  const editorState = useEditorState(editor, (ed) => ({
    isCodeBlock: ed.isActive("codeBlock"),
  }));

  useEffect(() => {
    let active = true;
    const check = async () => {
      await bubbleMenuPromise;
      if (active) {
        setLoaded(true);
      }
    };
    void check();
    return () => {
      active = false;
    };
  }, []);

  const shouldShow = useCallback(
    ({
      editor: ed,
      state,
    }: {
      editor: Editor;
      state: { selection: { empty: boolean } };
    }) => {
      const { selection } = state;
      if (!ed.isEditable) {
        return false;
      }
      if (selection.empty && !ed.isActive("codeBlock")) {
        return false;
      }
      if (!selection.empty && !isTextSelection(selection)) {
        return false;
      }
      return true;
    },
    []
  );

  if (!editor || !BubbleMenuComponent || !loaded) {
    return null;
  }

  const hasTextAlign = editor.extensionManager.extensions.some(
    (ext) => ext.name === "textAlign"
  );

  const isCodeBlockActive = editorState.isCodeBlock;

  return (
    <BubbleMenuComponent
      editor={editor}
      tippyOptions={{ hideOnClick: false, offset: [0, 8], placement: "top" }}
      shouldShow={shouldShow}
    >
      <div className="block-editor-bubble-menu">
        {isCodeBlockActive ? (
          <>
            <NodeSelector editor={editor} />
            <div className="block-editor-bubble-separator" />
            <LanguageSelector editor={editor} />
            <div className="block-editor-bubble-separator" />
            <button
              type="button"
              className="block-editor-bubble-btn block-editor-copy-btn"
              onMouseDown={(e) => e.preventDefault()}
              onClick={async () => {
                const { from, to } = editor.state.selection;
                const text = editor.state.doc.textBetween(from, to, "\n");
                try {
                  await navigator.clipboard.writeText(text);
                  setCopied(true);
                  setTimeout(() => setCopied(false), 2000);
                } catch {
                  /* ignored */
                }
              }}
            >
              <span
                className={`block-editor-copy-icon${copied ? " block-editor-copy-icon--copied" : ""}`}
              >
                {copied ? DEFAULT_ICONS.checkIcon : DEFAULT_ICONS.copyIcon}
              </span>
            </button>
          </>
        ) : (
          <>
            <NodeSelector editor={editor} />
            <div className="block-editor-bubble-separator" />
            <TextButtons editor={editor} />
            <div className="block-editor-bubble-separator" />
            <LinkSelector editor={editor} />
            {hasTextAlign && (
              <>
                <div className="block-editor-bubble-separator" />
                <TextAlignSelector editor={editor} />
              </>
            )}
          </>
        )}
      </div>
    </BubbleMenuComponent>
  );
};

import type { Editor } from "@tiptap/react";
import { useState, useEffect, useRef } from "react";

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T
): T => {
  const selectorRef = useRef(selector);

  const [state, setState] = useState<T>(() =>
    editor ? selector(editor) : (undefined as unknown as T)
  );

  useEffect(() => {
    selectorRef.current = selector;
  });

  useEffect(() => {
    if (!editor) {
      return;
    }
    const update = () => setState(selectorRef.current(editor));
    update();
    editor.on("selectionUpdate", update);
    editor.on("transaction", update);
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("transaction", update);
    };
  }, [editor]);

  return state;
};

export const copyBlock = async (editor: Editor): Promise<void> => {
  const { from } = editor.state.selection;
  const $from = editor.state.doc.resolve(from);
  const start = $from.before($from.depth);
  const end = $from.after($from.depth);
  if (start < 0 || end <= start) {
    return;
  }
  const text = editor.state.doc.textBetween(start, end, "\n", "\n");
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    /* ignored */
  }
};

export const deleteBlock = (editor: Editor) => {
  const { from } = editor.state.selection;
  const $from = editor.state.doc.resolve(from);
  const { depth } = $from;
  const start = $from.before(depth);
  const end = $from.after(depth);
  if (start < 0 || end <= start) {
    return;
  }
  editor.chain().focus().deleteRange({ from: start, to: end }).run();
};

export const CODE_BLOCK_LANGUAGES = [
  "javascript",
  "typescript",
  "html",
  "css",
  "json",
  "python",
  "rust",
  "go",
  "java",
  "c",
  "cpp",
  "ruby",
  "php",
  "swift",
  "kotlin",
  "sql",
  "bash",
  "markdown",
  "yaml",
  "xml",
  "plaintext",
] as const;

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { DEFAULT_ICONS } from "../icons";
import { useEditorState, copyBlock, deleteBlock } from "./utils";

interface SelectorResult {
  isParagraph: boolean;
  isHeading1: boolean;
  isHeading2: boolean;
  isHeading3: boolean;
  isBulletList: boolean;
  isOrderedList: boolean;
  isTaskList: boolean;
  isBlockquote: boolean;
  isCodeBlock: boolean;
}

interface NodeItem {
  command: (editor: Editor) => void;
  icon: React.ReactNode;
  isActive: (state: SelectorResult) => boolean;
  name: string;
}

interface NodeChain {
  run(): boolean;
  setParagraph(): NodeChain;
  toggleBlockquote(): NodeChain;
  toggleBulletList(): NodeChain;
  toggleCodeBlock(): NodeChain;
  toggleHeading(options: { level: number }): NodeChain;
  toggleOrderedList(): NodeChain;
  toggleTaskList(): NodeChain;
}

const nodeItems: NodeItem[] = [
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).setParagraph().run(),
    icon: DEFAULT_ICONS.slashTextIcon,
    isActive: (s) =>
      s.isParagraph &&
      !s.isBulletList &&
      !s.isOrderedList &&
      !s.isTaskList &&
      !s.isBlockquote &&
      !s.isCodeBlock,
    name: "Text",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 1 })
        .run(),
    icon: DEFAULT_ICONS.slashHeadingIcon,
    isActive: (s) => s.isHeading1,
    name: "Heading 1",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 2 })
        .run(),
    icon: DEFAULT_ICONS.slashHeadingIcon,
    isActive: (s) => s.isHeading2,
    name: "Heading 2",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 3 })
        .run(),
    icon: DEFAULT_ICONS.slashHeadingIcon,
    isActive: (s) => s.isHeading3,
    name: "Heading 3",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleBulletList().run(),
    icon: DEFAULT_ICONS.slashBulletListIcon,
    isActive: (s) => s.isBulletList,
    name: "Bullet List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleOrderedList().run(),
    icon: DEFAULT_ICONS.slashOrderedListIcon,
    isActive: (s) => s.isOrderedList,
    name: "Numbered List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleTaskList().run(),
    icon: DEFAULT_ICONS.slashTaskListIcon,
    isActive: (s) => s.isTaskList,
    name: "To-do List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleBlockquote().run(),
    icon: DEFAULT_ICONS.slashBlockquoteIcon,
    isActive: (s) => s.isBlockquote,
    name: "Quote",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleCodeBlock().run(),
    icon: DEFAULT_ICONS.slashCodeBlockIcon,
    isActive: (s) => s.isCodeBlock,
    name: "Code Block",
  },
];

export const NodeSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const editorState = useEditorState(editor, (ed) => ({
    isBlockquote: ed.isActive("blockquote"),
    isBulletList: ed.isActive("bulletList"),
    isCodeBlock: ed.isActive("codeBlock"),
    isHeading1: ed.isActive("heading", { level: 1 }),
    isHeading2: ed.isActive("heading", { level: 2 }),
    isHeading3: ed.isActive("heading", { level: 3 }),
    isOrderedList: ed.isActive("orderedList"),
    isParagraph: ed.isActive("paragraph"),
    isTaskList: ed.isActive("taskList"),
  }));

  const activeItems = nodeItems.filter((i) => i.isActive(editorState));
  const activeName =
    activeItems.length > 1 ? "Multiple" : (activeItems[0]?.name ?? "Text");
  const activeIcon = activeItems.length === 1 ? activeItems[0]?.icon : null;

  return (
    <div style={{ position: "relative" }}>
      <button
        type="button"
        className="block-editor-bubble-btn"
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        {activeIcon && (
          <span className="block-editor-bubble-dropdown-icon">
            {activeIcon}
          </span>
        )}
        <span className="block-editor-bubble-btn-text">{activeName}</span>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </button>
      {open && (
        <>
          <div
            className="block-editor-bubble-overlay"
            role="presentation"
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <div className="block-editor-bubble-dropdown">
            {nodeItems.map((item, i) => (
              <button
                key={i}
                type="button"
                className={`block-editor-bubble-dropdown-item${item.isActive(editorState) ? " block-editor-bubble-dropdown-item--active" : ""}`}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  item.command(editor);
                  setOpen(false);
                }}
              >
                <span className="block-editor-bubble-dropdown-icon">
                  {item.icon}
                </span>
                <span>{item.name}</span>
                {item.isActive(editorState) && (
                  <span className="block-editor-bubble-dropdown-icon">
                    {DEFAULT_ICONS.checkIcon}
                  </span>
                )}
              </button>
            ))}
            <div className="block-editor-bubble-dropdown-divider" />
            <button
              type="button"
              className="block-editor-bubble-dropdown-item"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                copyBlock(editor);
                setOpen(false);
              }}
            >
              <span className="block-editor-bubble-dropdown-icon">
                {DEFAULT_ICONS.copyIcon}
              </span>
              <span>Copy</span>
            </button>
            <button
              type="button"
              className="block-editor-bubble-dropdown-item block-editor-bubble-dropdown-item--danger"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                deleteBlock(editor);
                setOpen(false);
              }}
            >
              <span className="block-editor-bubble-dropdown-icon">
                {DEFAULT_ICONS.deleteIcon}
              </span>
              <span>Delete</span>
            </button>
          </div>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";

import { DEFAULT_ICONS } from "../icons";
import { useEditorState } from "./utils";

interface TextSelectorResult {
  isBold: boolean;
  isItalic: boolean;
  isUnderline: boolean;
  isStrike: boolean;
  isCode: boolean;
}

interface ToggleableChain {
  run(): boolean;
  toggleBold(): ToggleableChain;
  toggleCode(): ToggleableChain;
  toggleItalic(): ToggleableChain;
  toggleStrike(): ToggleableChain;
  toggleUnderline(): ToggleableChain;
}

const textItems = [
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleBold().run(),
    icon: DEFAULT_ICONS.boldIcon,
    isActive: (s: TextSelectorResult) => s.isBold,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleItalic().run(),
    icon: DEFAULT_ICONS.italicIcon,
    isActive: (s: TextSelectorResult) => s.isItalic,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleUnderline().run(),
    icon: DEFAULT_ICONS.underlineIcon,
    isActive: (s: TextSelectorResult) => s.isUnderline,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleStrike().run(),
    icon: DEFAULT_ICONS.strikethroughIcon,
    isActive: (s: TextSelectorResult) => s.isStrike,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleCode().run(),
    icon: DEFAULT_ICONS.codeIcon,
    isActive: (s: TextSelectorResult) => s.isCode,
  },
];

export const TextButtons = ({ editor }: { editor: Editor }) => {
  const editorState = useEditorState(editor, (ed) => ({
    isBold: ed.isActive("bold"),
    isCode: ed.isActive("code"),
    isItalic: ed.isActive("italic"),
    isStrike: ed.isActive("strike"),
    isUnderline: ed.isActive("underline"),
  }));

  return (
    <div className="block-editor-bubble-group">
      {textItems.map((item, i) => (
        <button
          key={i}
          type="button"
          className={`block-editor-bubble-btn${item.isActive(editorState) ? " block-editor-bubble-btn--active" : ""}`}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => item.command(editor)}
        >
          {item.icon}
        </button>
      ))}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { DEFAULT_ICONS } from "../icons";
import { useEditorState } from "./utils";

interface AlignSelectorResult {
  isAlignLeft: boolean;
  isAlignCenter: boolean;
  isAlignRight: boolean;
}

interface AlignableChain {
  run(): boolean;
  setTextAlign(alignment: "center" | "left" | "right"): AlignableChain;
}

const alignItems = [
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("left")
        .run(),
    icon: DEFAULT_ICONS.alignLeftIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignLeft,
    label: "Left",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("center")
        .run(),
    icon: DEFAULT_ICONS.alignCenterIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignCenter,
    label: "Center",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("right")
        .run(),
    icon: DEFAULT_ICONS.alignRightIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignRight,
    label: "Right",
  },
];

export const TextAlignSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const editorState = useEditorState(editor, (ed) => ({
    isAlignCenter: ed.isActive({ textAlign: "center" }),
    isAlignLeft:
      !ed.isActive({ textAlign: "center" }) &&
      !ed.isActive({ textAlign: "right" }),
    isAlignRight: ed.isActive({ textAlign: "right" }),
  }));

  const activeItem = alignItems.find((i) => i.isActive(editorState));

  return (
    <div style={{ position: "relative" }}>
      <button
        type="button"
        className="block-editor-bubble-btn"
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        <span className="block-editor-bubble-dropdown-icon">
          {activeItem ? activeItem.icon : DEFAULT_ICONS.alignLeftIcon}
        </span>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </button>
      {open && (
        <>
          <div
            className="block-editor-bubble-overlay"
            role="presentation"
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <div
            className="block-editor-bubble-dropdown block-editor-bubble-dropdown--align"
            style={{ left: "auto", right: 0 }}
          >
            {alignItems.map((item, i) => (
              <button
                key={i}
                type="button"
                className={`block-editor-bubble-dropdown-item${item.isActive(editorState) ? " block-editor-bubble-dropdown-item--active" : ""}`}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  item.command(editor);
                  setOpen(false);
                }}
              >
                <span className="block-editor-bubble-dropdown-icon">
                  {item.icon}
                </span>
                <span>{item.label}</span>
                {item.isActive(editorState) && (
                  <span className="block-editor-bubble-dropdown-icon">
                    {DEFAULT_ICONS.checkIcon}
                  </span>
                )}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState, useRef, useCallback, useEffect } from "react";

import { DEFAULT_ICONS } from "../icons";

interface LinkableChain {
  extendMarkRange(type: string): LinkableChain;
  run(): boolean;
  setLink(options: { href: string }): LinkableChain;
  unsetLink(): LinkableChain;
}

export const LinkSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const [{ isLink, linkUrl }, setLinkState] = useState(() => ({
    isLink: editor.isActive("link"),
    linkUrl: editor.getAttributes("link").href || "",
  }));

  useEffect(() => {
    const update = () => {
      setLinkState({
        isLink: editor.isActive("link"),
        linkUrl: editor.getAttributes("link").href || "",
      });
    };
    editor.on("selectionUpdate", update);
    editor.on("transaction", update);
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("transaction", update);
    };
  }, [editor]);

  const handleSubmit = useCallback(
    (evt: React.FormEvent) => {
      evt.preventDefault();
      let url = inputRef.current?.value?.trim();
      if (!url) {
        return;
      }
      if (!/^https?:\/\//i.test(url)) {
        url = `https://${url}`;
      }
      (editor.chain().focus() as unknown as LinkableChain)
        .extendMarkRange("link")
        .setLink({ href: url })
        .run();
      setOpen(false);
    },
    [editor]
  );

  const handleUnlink = useCallback(() => {
    (editor.chain().focus() as unknown as LinkableChain).unsetLink().run();
    setOpen(false);
  }, [editor]);

  return (
    <div style={{ position: "relative" }}>
      <button
        type="button"
        className={`block-editor-bubble-btn${isLink ? " block-editor-bubble-btn--active" : ""}`}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
        title="Link"
      >
        {DEFAULT_ICONS.linkIcon}
      </button>
      {open && (
        <>
          <div
            className="block-editor-bubble-overlay"
            role="presentation"
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <div
            className="block-editor-bubble-dropdown"
            style={{ left: "auto", minWidth: "220px", right: 0 }}
          >
            <form className="block-editor-link-form" onSubmit={handleSubmit}>
              <input
                ref={inputRef}
                type="text"
                className="block-editor-link-input"
                placeholder="Paste a link..."
                defaultValue={linkUrl}
                autoFocus
              />
              <div className="block-editor-link-actions">
                {isLink && (
                  <button
                    type="button"
                    className="block-editor-bubble-dropdown-item block-editor-bubble-dropdown-item--danger"
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={handleUnlink}
                    style={{ justifyContent: "center" }}
                  >
                    <span className="block-editor-bubble-dropdown-icon">
                      {DEFAULT_ICONS.unlinkIcon}
                    </span>
                    <span>Remove</span>
                  </button>
                )}
                <button
                  type="submit"
                  className="block-editor-bubble-dropdown-item"
                  onMouseDown={(e) => e.preventDefault()}
                  style={{ justifyContent: "center" }}
                >
                  <span className="block-editor-bubble-dropdown-icon">
                    {DEFAULT_ICONS.checkIcon}
                  </span>
                  <span>{isLink ? "Update" : "Add"}</span>
                </button>
              </div>
            </form>
          </div>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { useBlockEditorContext } from "../context";
import { DEFAULT_ICONS } from "../icons";
import { CODE_BLOCK_LANGUAGES, useEditorState } from "./utils";

export const LanguageSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const { icons } = useBlockEditorContext();

  const { currentLanguage } = useEditorState(editor, (ed) => ({
    currentLanguage: ed.getAttributes("codeBlock").language || "javascript",
  }));

  const langIcon =
    icons.languageIcons[currentLanguage] ?? icons.codeBlockLanguageIcon;

  return (
    <div style={{ position: "relative" }}>
      <button
        type="button"
        className="block-editor-bubble-btn"
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        <span className="block-editor-bubble-dropdown-icon">{langIcon}</span>
        <span className="block-editor-bubble-btn-text">{currentLanguage}</span>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </button>
      {open && (
        <>
          <div
            className="block-editor-bubble-overlay"
            role="presentation"
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <div
            className="block-editor-bubble-dropdown block-editor-bubble-dropdown--language"
            style={{ left: "auto", right: 0 }}
          >
            {CODE_BLOCK_LANGUAGES.map((lang) => (
              <button
                key={lang}
                type="button"
                className={`block-editor-bubble-dropdown-item${currentLanguage === lang ? " block-editor-bubble-dropdown-item--active" : ""}`}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  editor
                    .chain()
                    .focus()
                    .updateAttributes("codeBlock", { language: lang })
                    .run();
                  setOpen(false);
                }}
              >
                <span className="block-editor-bubble-dropdown-icon">
                  {icons.languageIcons[lang] ?? icons.codeBlockLanguageIcon}
                </span>
                <span>{lang}</span>
                {currentLanguage === lang && (
                  <span className="block-editor-bubble-dropdown-icon">
                    {DEFAULT_ICONS.checkIcon}
                  </span>
                )}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/core";
import { createContext, useContext } from "react";
import type { ReactNode } from "react";

import type { BlockEditorIcons } from "./icons";
import { DEFAULT_ICONS } from "./icons";
import { DEFAULT_BLOCK_EDITOR_LABELS } from "./labels";
import type { BlockEditorContextValue, BlockEditorLabels } from "./types";

const BlockEditorContext = createContext<BlockEditorContextValue | null>(null);

export const useBlockEditorContext = () => {
  const ctx = useContext(BlockEditorContext);
  if (!ctx) {
    throw new Error("BlockEditor components must be used within <BlockEditor>");
  }
  return ctx;
};

export interface BlockEditorProviderProps {
  editor: Editor | null;
  children: ReactNode;
  labels?: Partial<BlockEditorLabels>;
  icons?: Partial<BlockEditorIcons>;
}

export const BlockEditorProvider = ({
  editor,
  children,
  labels,
  icons,
}: BlockEditorProviderProps) => {
  const mergedLabels = { ...DEFAULT_BLOCK_EDITOR_LABELS, ...labels };
  const mergedIcons = { ...DEFAULT_ICONS, ...icons };

  return (
    <BlockEditorContext.Provider
      value={{
        editor,
        icons: mergedIcons,
        labels: mergedLabels,
      }}
    >
      {children}
    </BlockEditorContext.Provider>
  );
};

import type { BlockEditorLabels } from "./types";

export const DEFAULT_BLOCK_EDITOR_LABELS: BlockEditorLabels = {
  blockquoteLabel: "Quote",
  bulletListLabel: "Bullet list",
  codeBlockLabel: "Code",
  dividerLabel: "Divider",
  headingLabel: "Heading",
  orderedListLabel: "Numbered list",
  paragraphLabel: "Text",
  taskListLabel: "To-do list",
};

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";

import type { BlockEditorIcons } from "./icons";

export interface BlockEditorLabels {
  paragraphLabel?: string;
  headingLabel?: string;
  bulletListLabel?: string;
  orderedListLabel?: string;
  taskListLabel?: string;
  blockquoteLabel?: string;
  codeBlockLabel?: string;
  dividerLabel?: string;
}

export interface BlockEditorProps {
  editor: Editor | null;
  children?: ReactNode;
  className?: string;
  labels?: Partial<BlockEditorLabels>;
  icons?: Partial<BlockEditorIcons>;
}

export interface BlockEditorContextValue {
  editor: Editor | null;
  labels: BlockEditorLabels;
  icons: BlockEditorIcons;
}

/* Block Editor styles using shadcn CSS variables */
.block-editor {
  position: relative;
  width: 100%;
}

.block-editor-content {
  width: 100%;
}

.block-editor-content .ProseMirror {
  outline: none;
  min-height: 200px;
  padding: 0.5rem 0 0.5rem 2rem;
  overflow: auto hidden;
  transition: opacity 150ms ease-out;
}

.block-editor-content .ProseMirror p.is-editor-empty:first-child::before {
  color: var(--muted-foreground);
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  transition: opacity 150ms ease-out;
}

.block-editor-content .ProseMirror .is-empty::before {
  color: var(--muted-foreground);
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  transition: opacity 150ms ease-out;
}

/* Tiptap drag handle (from @tiptap/extension-drag-handle-react) */
.drag-handle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.5rem;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--muted-foreground);
  cursor: grab;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    opacity 150ms ease-out,
    transform 100ms ease-out;
  opacity: 0;
}

.drag-handle:hover {
  background: var(--accent);
  color: var(--accent-foreground);
  opacity: 1;
}

.drag-handle:active {
  cursor: grabbing;
  transform: scale(0.9);
}

.block-editor-content .ProseMirror:hover ~ .drag-handle,
.block-editor-content:hover .drag-handle {
  opacity: 1;
}

/* ── Bubble Menu & Dropdowns ── */
@keyframes bubble-pop-in {
  0% {
    opacity: 0;
    transform: scale(0.96) translateY(4px);
